package com.coffeeshop.service;import com.coffeeshop.dto.SettingCommands;import com.coffeeshop.model.SettingModels;import com.coffeeshop.repository.SettingRepository;import java.math.BigDecimal;import java.util.*;public final class SettingService{private static final Set<String>TYPES=Set.of("STRING","INTEGER","DECIMAL","BOOLEAN");private final SettingRepository repository;public SettingService(SettingRepository r){repository=Objects.requireNonNull(r);}public List<SettingModels.Setting>settings(String search){return repository.find(search);}public long save(SettingCommands.Save q,long user){Objects.requireNonNull(q);if(user<=0)throw new IllegalArgumentException("An authenticated administrator is required.");String key=required(q.key(),150,"Setting key");String normalizedKey=key.toLowerCase(Locale.ROOT);if(normalizedKey.startsWith("database.")||normalizedKey.contains("password")||normalizedKey.contains("secret")||normalizedKey.contains("credential")||normalizedKey.contains("token"))throw new IllegalArgumentException("Credentials and secrets must remain in external configuration.");String type=required(q.type(),20,"Value type").toUpperCase(Locale.ROOT),value=required(q.value(),2000,"Setting value");if(!TYPES.contains(type))throw new IllegalArgumentException("Select a valid value type.");validate(type,value);if(q.id()!=null&&(q.version()==null||q.version().length==0))throw new IllegalArgumentException("Refresh this setting and try again.");return repository.save(new SettingCommands.Save(q.id(),key,value,type,optional(q.description(),500,"Description"),q.version()),user);}private static void validate(String t,String v){try{switch(t){case"INTEGER"->Long.parseLong(v);case"DECIMAL"->new BigDecimal(v);case"BOOLEAN"->{if(!v.equalsIgnoreCase("true")&&!v.equalsIgnoreCase("false"))throw new IllegalArgumentException();}default->{}}}catch(Exception e){throw new IllegalArgumentException("Value does not match the selected "+t.toLowerCase(Locale.ROOT)+" type.");}}private static String required(String v,int m,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>m)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int m,String n){return v==null||v.isBlank()?null:required(v,m,n);}}
